#!/usr/bin/env python3
"""Deterministic input generator for RPG Session Initialization benchmark."""

import json
import random
from pathlib import Path
from typing import Any

# Fixed seed for reproducibility
RANDOM_SEED = 1337

# Genre templates for deterministic generation
GENRE_TEMPLATES = {
    "cyberpunk": {
        "setting": "Neo-Tokyo 2089",
        "factions": ["Arasaka Corp", "Netrunners Guild", "Yakuza Remnant"],
        "attributes": ["Cool", "Chrome", "Hack", "Street"],
        "starting_items": ["Plasma Pistol", "Deck", "Access Keycard"],
        "archetypes": ["Netrunner", "Solo", "Techie", "Face"]
    },
    "fantasy": {
        "setting": "Kingdom of Eldoria",
        "factions": ["The High Council", "Shadow Cult", "Dwarven Clans"],
        "attributes": ["STR", "DEX", "INT", "WIS"],
        "starting_items": ["Iron Sword", "Leather Armor", "Healing Potion"],
        "archetypes": ["Warrior", "Mage", "Rogue", "Cleric"]
    },
    "horror": {
        "setting": "Arkham, 1925",
        "factions": ["Miskatonic University", "Miskatonic Police", "Ithaqua Cult"],
        "attributes": ["POW", "SAN", "DEX", "INT"],
        "starting_items": ["Revolver", "Flashlight", "Diary"],
        "archetypes": ["Investigator", "Doctor", "Occultist", "Cop"]
    }
}

class InputGenerator:
    """Generates deterministic test inputs for RPG benchmark."""

    def __init__(self, seed: int = RANDOM_SEED, output_dir: Path = Path(".")):
        self.rng = random.Random(seed)
        self.output_dir = output_dir
        self.campaign_name = f"benchmark_{seed}"

    def generate_campaign_config(self) -> dict:
        """Generate campaign configuration with deterministic choices."""
        genre = self.rng.choice(list(GENRE_TEMPLATES.keys()))
        template = GENRE_TEMPLATES[genre]

        return {
            "campaign_id": self.campaign_name,
            "genre": genre,
            "setting": template["setting"],
            "system": "d20",
            "difficulty": "hard",
            "max_players": 1,
            "session_limit": 10,
            "flags": {
                "allow_meta_comments": True,
                "track_clocks": True,
                "verbose_dice": True
            }
        }

    def generate_initial_state(self, campaign_config: dict) -> dict:
        """Generate initial world state."""
        genre = campaign_config["genre"]
        template = GENRE_TEMPLATES[genre]

        return {
            "time": "Session-01",
            "location": f"Starting Point - {template['setting']}",
            "weather": self.rng.choice(["clear", "rain", "fog", "storm"]),
            "threat_level": 1,
            "clocks": {
                "main_threat": 0,
                "time_limit": 4,
                "discovery": 0
            },
            "flags": {
                "session_started": False,
                "character_created": False,
                "first_encounter": False
            },
            "world_state": {
                "factions": template["factions"],
                "active_plot_hooks": [],
                "completed_objectives": []
            }
        }

    def generate_player_preferences(self, campaign_config: dict) -> dict:
        """Generate player's Session Zero responses."""
        genre = campaign_config["genre"]
        template = GENRE_TEMPLATES[genre]

        # Deterministic character creation
        archetype = self.rng.choice(template["archetypes"])
        starting_items = self.rng.sample(template["starting_items"], 2)

        # Attribute point buy (20 points to distribute, max 5 per attr)
        attributes = {}
        points_remaining = 20
        for attr in template["attributes"]:
            if points_remaining > 0:
                val = min(5, max(1, self.rng.randint(1, 5)))
                attributes[attr] = val
                points_remaining -= val
        # Distribute remaining points
        while points_remaining > 0:
            for attr in template["attributes"]:
                if attributes[attr] < 5 and points_remaining > 0:
                    attributes[attr] += 1
                    points_remaining -= 1

        return {
            "session_zero_responses": {
                "step1_world": {
                    "setting_preference": genre,
                    "hook": f"A mysterious summons to {template['setting']}",
                    "tone": self.rng.choice(["gritty", "heroic", "mysterious"])
                },
                "step2_factions": {
                    "primary_faction": template["factions"][0],
                    "rival_faction": template["factions"][1],
                    "player_alignment": "neutral"
                },
                "step3_character": {
                    "name": self.rng.choice(["Alex", "Jordan", "Sam", "Casey", "Riley"]),
                    "archetype": archetype,
                    "attributes": attributes,
                    "drive": "seeking truth",
                    "flaw": "trust issues",
                    "appearance": "scarred, weathered"
                },
                "step4_system": {
                    "resolution_system": "d20",
                    "crit_on": 20,
                    "fail_on": 1,
                    "advantage_system": True
                }
            },
            "preferences": {
                "narrative_style": "descriptive",
                "dice_visibility": "hidden",
                "difficulty_preference": "challenging"
            }
        }

    def generate_all_inputs(self) -> dict:
        """Generate all required inputs and save them."""
        inputs = {}

        # Generate campaign config first
        inputs["campaign_config"] = self.generate_campaign_config()

        # Generate initial state based on config
        inputs["initial_state"] = self.generate_initial_state(inputs["campaign_config"])

        # Generate player preferences
        inputs["player_preferences"] = self.generate_player_preferences(inputs["campaign_config"])

        # Save all inputs
        inputs_dir = self.output_dir / "inputs"
        inputs_dir.mkdir(parents=True, exist_ok=True)

        for name, data in inputs.items():
            filepath = inputs_dir / f"{name}.json"
            with open(filepath, "w", encoding="utf-8") as f:
                json.dump(data, f, indent=2)
            print(f"Generated: {filepath}")

        return inputs


def main():
    """Main entry point."""
    generator = InputGenerator(seed=RANDOM_SEED, output_dir=Path("."))
    inputs = generator.generate_all_inputs()

    # Also generate expected outputs for grading
    expected_dir = Path("expected")
    expected_dir.mkdir(exist_ok=True)

    # Expected world state after session zero
    expected_world = {
        "time": "Session-01",
        "location": f"Starting Point - {GENRE_TEMPLATES['cyberpunk']['setting']}",
