        "flags": {
            "session_started": True,
            "character_created": True,
            "first_encounter": False
        }
    }

    with open(expected_dir / "world.json", "w") as f:
        json.dump(expected_world, f, indent=2)

    print("Input generation complete!")
    return inputs


if __name__ == "__main__":
    main()
